/**
 * 极简 IndexedDB 内存实现
 *
 * 容器无网络，装不了 fake-indexeddb。这里实现 memoryHistoryDB.js 实际用到的
 * 那一部分 API，让被跳过的数据库测试也能跑起来。
 *
 * 覆盖：open/upgrade、objectStore 增删查、autoIncrement、keyPath、
 *      索引的 getAll(query)、游标遍历、事务 oncomplete。
 */

function later(fn) {
    setTimeout(fn, 0);
}

class FakeRequest {
    constructor() {
        this.result = undefined;
        this.error = null;
        this.onsuccess = null;
        this.onerror = null;
        this.onupgradeneeded = null;
        this.transaction = null;
    }
    _succeed(result) {
        this.result = result;
        later(() => this.onsuccess && this.onsuccess({ target: this }));
    }
    _fail(err) {
        this.error = err;
        later(() => this.onerror && this.onerror({ target: this }));
    }
}

class FakeIndex {
    constructor(store, name, keyPath) {
        this.store = store;
        this.name = name;
        this.keyPath = keyPath;
    }
    _extract(record) {
        if (Array.isArray(this.keyPath)) return this.keyPath.map((k) => record[k]);
        return record[this.keyPath];
    }
    _matches(record, query) {
        if (query === undefined || query === null) return true;
        const v = this._extract(record);
        if (Array.isArray(query)) return JSON.stringify(v) === JSON.stringify(query);
        return v === query;
    }
    getAll(query) {
        const req = new FakeRequest();
        const out = [...this.store._data.values()].filter((r) => this._matches(r, query));
        req._succeed(out);
        return req;
    }
    openCursor(query, direction) {
        const req = new FakeRequest();
        let rows = [...this.store._data.entries()].filter(([, r]) => this._matches(r, query));
        if (direction === 'prev') rows.reverse();
        let i = 0;
        const step = () => {
            if (i >= rows.length) {
                req.result = null;
                later(() => req.onsuccess && req.onsuccess({ target: req }));
                return;
            }
            const [key, value] = rows[i++];
            req.result = {
                key,
                primaryKey: key,
                value,
                continue: () => later(step),
                delete: () => {
                    this.store._data.delete(key);
                    const r = new FakeRequest();
                    r._succeed(undefined);
                    return r;
                },
            };
            later(() => req.onsuccess && req.onsuccess({ target: req }));
        };
        later(step);
        return req;
    }
    count(query) {
        const req = new FakeRequest();
        req._succeed([...this.store._data.values()].filter((r) => this._matches(r, query)).length);
        return req;
    }
}

class FakeObjectStore {
    constructor(name, options = {}) {
        this.name = name;
        this.keyPath = options.keyPath || null;
        this.autoIncrement = !!options.autoIncrement;
        this._data = new Map();
        this._indexes = new Map();
        this._nextKey = 1;
        this.indexNames = {
            contains: (n) => this._indexes.has(n),
        };
    }
    createIndex(name, keyPath) {
        const idx = new FakeIndex(this, name, keyPath);
        this._indexes.set(name, idx);
        return idx;
    }
    index(name) {
        const idx = this._indexes.get(name);
        if (!idx) throw new Error(`索引不存在: ${name}`);
        return idx;
    }
    _keyOf(value, explicitKey) {
        if (explicitKey !== undefined) return explicitKey;
        if (this.keyPath && value && value[this.keyPath] !== undefined) return value[this.keyPath];
        if (this.autoIncrement) return this._nextKey++;
        return undefined;
    }
    add(value, key) {
        const req = new FakeRequest();
        const k = this._keyOf(value, key);
        if (this.keyPath && value && typeof value === 'object' && value[this.keyPath] === undefined) {
            value[this.keyPath] = k;
        }
        this._data.set(k, value);
        req._succeed(k);
        return req;
    }
    put(value, key) {
        return this.add(value, key);
    }
    get(key) {
        const req = new FakeRequest();
        req._succeed(this._data.get(key));
        return req;
    }
    getAll() {
        const req = new FakeRequest();
        req._succeed([...this._data.values()]);
        return req;
    }
    getAllKeys() {
        const req = new FakeRequest();
        req._succeed([...this._data.keys()]);
        return req;
    }
    delete(key) {
        const req = new FakeRequest();
        this._data.delete(key);
        req._succeed(undefined);
        return req;
    }
    clear() {
        const req = new FakeRequest();
        this._data.clear();
        req._succeed(undefined);
        return req;
    }
    count() {
        const req = new FakeRequest();
        req._succeed(this._data.size);
        return req;
    }
    openCursor(query, direction) {
        const req = new FakeRequest();
        let rows = [...this._data.entries()];
        if (direction === 'prev') rows.reverse();
        let i = 0;
        const step = () => {
            if (i >= rows.length) {
                req.result = null;
                later(() => req.onsuccess && req.onsuccess({ target: req }));
                return;
            }
            const [key, value] = rows[i++];
            req.result = {
                key,
                primaryKey: key,
                value,
                continue: () => later(step),
                delete: () => {
                    this._data.delete(key);
                    const r = new FakeRequest();
                    r._succeed(undefined);
                    return r;
                },
            };
            later(() => req.onsuccess && req.onsuccess({ target: req }));
        };
        later(step);
        return req;
    }
}

class FakeTransaction {
    constructor(db, storeNames) {
        this.db = db;
        this.storeNames = storeNames;
        this.oncomplete = null;
        this.onerror = null;
        this.onabort = null;
        later(() => this.oncomplete && this.oncomplete({}));
    }
    objectStore(name) {
        const s = this.db._stores.get(name);
        if (!s) throw new Error(`对象仓库不存在: ${name}`);
        return s;
    }
    abort() {
        later(() => this.onabort && this.onabort({}));
    }
}

class FakeDatabase {
    constructor(name, version) {
        this.name = name;
        this.version = version;
        this._stores = new Map();
        this.onversionchange = null;
        this.onclose = null;
        this.objectStoreNames = {
            contains: (n) => this._stores.has(n),
            get length() {
                return 0;
            },
        };
    }
    createObjectStore(name, options) {
        const store = new FakeObjectStore(name, options);
        this._stores.set(name, store);
        return store;
    }
    deleteObjectStore(name) {
        this._stores.delete(name);
    }
    transaction(names, mode) {
        return new FakeTransaction(this, Array.isArray(names) ? names : [names]);
    }
    close() {
        if (this.onclose) this.onclose({});
    }
}

const databases = new Map();

const fakeIndexedDB = {
    open(name, version = 1) {
        const req = new FakeRequest();
        later(() => {
            let db = databases.get(name);
            const isNew = !db;
            const oldVersion = db ? db.version : 0;

            if (isNew) {
                db = new FakeDatabase(name, version);
                databases.set(name, db);
            }

            req.result = db;

            if (isNew || version > oldVersion) {
                db.version = version;
                const tx = new FakeTransaction(db, []);
                req.transaction = {
                    objectStore: (n) => db._stores.get(n),
                    oncomplete: null,
                };
                if (req.onupgradeneeded) {
                    req.onupgradeneeded({ target: req, oldVersion, newVersion: version });
                }
            }
            later(() => req.onsuccess && req.onsuccess({ target: req }));
        });
        return req;
    },
    deleteDatabase(name) {
        const req = new FakeRequest();
        databases.delete(name);
        req._succeed(undefined);
        return req;
    },
    databases: async () => [...databases.keys()].map((name) => ({ name })),
};

globalThis.indexedDB = fakeIndexedDB;
globalThis.IDBKeyRange = {
    only: (v) => v,
    bound: (a, b) => ({ lower: a, upper: b }),
    lowerBound: (a) => ({ lower: a }),
    upperBound: (b) => ({ upper: b }),
};

export default fakeIndexedDB;
export { fakeIndexedDB as indexedDB };
